<script setup lang="ts">
import {computed,ref,shallowRef,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import type {components} from '../../shared/api/generated';import {importFormat} from '../../shared/document-formats';import {prepareUpload} from './upload-bytes';import Icon from '../../shared/Icon.vue';
const props=defineProps<{meetingId:string;active:boolean;autoAdvance?:boolean;taskPresent?:boolean;confirmed?:boolean;observedTask?:string|null;observedTaskId?:string|null;observedInputId?:string|null}>(),emit=defineEmits<{changed:[];processed:[];editFiles:[];materials:[kind:'materials'|'local'|'library']}>(),{session,uploads,uploadQueue:queue,recordingStore,tasks}=useApplication();type FileItem=components['schemas']['CompletedFileSummary'];
const files=shallowRef<FileItem[]>([]),loading=ref(false),error=ref<string|null>(null),more=ref(false),processing=ref(false),taskState=ref<string|null>(null),recorded=ref(false),dock=ref<HTMLElement>();let boundKey:string|null=null,bindingKey:string|null=null,bindingFlight:Promise<void>|null=null;let pollTask:string|null=null,observer:ResizeObserver|null=null;let epoch=0,controller:AbortController|null=null,timer:ReturnType<typeof setTimeout>|null=null;
const actor=()=>session.current.value?.actor.enterpriseId??null;
const canStart=computed(()=>files.value.length>0&&!more.value&&!loading.value&&!processing.value&&queue.ready.value&&!queue.blocked.value&&files.value.every(f=>f.originalPurpose==='TRANSCRIPT_INPUT'&&f.intakeEligibility.state==='ELIGIBLE'&&!!importFormat(f.displayName)));
function reset(){epoch++;controller?.abort();controller=null;if(timer)clearTimeout(timer);timer=null;files.value=[];loading.value=false;error.value=null;more.value=false;processing.value=false;taskState.value=null;recorded.value=false;pollTask=null;boundKey=null;bindingKey=null;bindingFlight=null;}
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(v);
function selectedInput(){const ack=queue.importCommand.state.value==='ACKNOWLEDGED'?queue.importCommand.ack.value:null;if(ack&&uuid(ack.inputId)&&uuid(ack.taskId))return{input:ack.inputId,task:ack.taskId};if(uuid(props.observedInputId)&&uuid(props.observedTaskId))return{input:props.observedInputId,task:props.observedTaskId};return null;}
async function bindFiles(input:string,task:string,turn:number){
 const key=input+'|'+task;if(boundKey===key)return;if(bindingKey===key&&bindingFlight)return bindingFlight;bindingKey=key;files.value=[];loading.value=true;const who=actor(),id=props.meetingId,request=controller??new AbortController();controller=request;const active=()=>turn===epoch&&who===actor()&&id===props.meetingId&&!request.signal.aborted;
 const run=async()=>{const source=await uploads.input(id,input,task,request.signal);if(!active())return;const actual:FileItem[]=[];for(const f of source.files){const receipt=await uploads.receipt(id,f.uploadId,request.signal);if(!active())return;const item=receipt.completed;if(!item||item.fileId!==f.fileId||item.sha256!==f.sha256||item.sizeBytesToken!==f.sizeBytesToken||item.originalPurpose!=='TRANSCRIPT_INPUT')throw Error('任务锁定文件与原上传结果不匹配');actual.push(item);}if(active()){files.value=actual;more.value=false;boundKey=key;}};
 const flight=run();bindingFlight=flight;try{await flight;}finally{if(bindingFlight===flight){bindingFlight=null;bindingKey=null;if(active())loading.value=false;}}
}
async function load(){reset();const who=actor(),id=props.meetingId;if(!who||!props.active)return;const turn=epoch,request=new AbortController();controller=request;loading.value=true;const active=()=>turn===epoch&&who===actor()&&id===props.meetingId&&!request.signal.aborted;
 try{const initial=selectedInput();if(initial){await bindFiles(initial.input,initial.task,turn);}else{const page=await uploads.completedFiles(id,null,request.signal);if(!active())return;const nowSelected=selectedInput();if(nowSelected){await bindFiles(nowSelected.input,nowSelected.task,turn);}else{let selected=page.items.filter(f=>f.originalPurpose==='TRANSCRIPT_INPUT');const local=await recordingStore.load(who,id);if(!active())return;
  if(local?.finished){recorded.value=true;const ordered:FileItem[]=[];for(const part of local.parts.filter(p=>p.bytes>0)){const file=await recordingStore.file(local,part),prepared=await prepareUpload(file,request.signal);if(!active())return;const matching=selected.filter(f=>f.displayName===part.name&&f.sizeBytes===part.bytes&&f.sha256===prepared.begin.sha256);if(matching.length!==1)throw Error('录音原文件暂无法完整核对，请保留原文件并重试');ordered.push(matching[0]!);}selected=[...ordered,...selected.filter(f=>!ordered.some(p=>p.fileId===f.fileId))];}
  if(!active())return;const latest=selectedInput();if(latest)await bindFiles(latest.input,latest.task,turn);else{files.value=selected;more.value=page.nextCursor!==null;}}}
  if(!active())return;if(!queue.ready.value)await queue.open();if(active()&&queue.importCommand.state.value==='ACKNOWLEDGED'&&queue.importCommand.ack.value)beginObservation(queue.importCommand.ack.value.taskId);
 }catch(cause){if(active())error.value=cause instanceof Error?cause.message:'会议主文件暂不可用，请重试。';}finally{if(active())loading.value=false;}}
async function observe(turn:number,task:string){if(turn!==epoch||!actor()||!props.active)return;const request=controller??new AbortController();controller=request;try{const result=await tasks.list(props.meetingId,'TRANSCRIPT_IMPORT_V1',null,request.signal);if(turn!==epoch)return;const found=result.items.find(t=>t.taskId===task);if(!found)throw Error('原处理任务暂未查到，请刷新处理记录');if(!uuid(found.inputId))throw Error('原处理输入暂不可用');await bindFiles(found.inputId,found.taskId,turn);if(turn!==epoch)return;taskState.value=found.state;emit('changed');if(found.state==='SUCCEEDED'){processing.value=false;if(props.autoAdvance)emit('processed');return;}if(['FAILED','CANCELLED','STALE'].includes(found.state)){processing.value=false;error.value='转写处理未完成，请查看处理记录。';return;}timer=setTimeout(()=>void observe(turn,task),2000);}catch(cause){if(turn===epoch){processing.value=false;error.value=cause instanceof Error?cause.message:'处理状态暂不可用，请刷新。';}}}
function beginObservation(task:string){if(pollTask===task)return;pollTask=task;processing.value=true;void observe(epoch,task);}
async function start(){if(!canStart.value&&queue.importCommand.state.value==='EMPTY')return;processing.value=true;error.value=null;const turn=epoch;try{if(['FAILED','CANCELLED','STALE'].includes(taskState.value??'')&&queue.importCommand.state.value==='ACKNOWLEDGED'){queue.newBatch();taskState.value=null;pollTask=null;if(timer)clearTimeout(timer);timer=null;}await queue.submitImport(files.value.map(f=>({fileId:f.fileId,name:f.displayName})));if(turn!==epoch)return;const ack=queue.importCommand.ack.value;if(queue.importCommand.state.value!=='ACKNOWLEDGED'||!ack)throw Error(queue.error.value??'原处理请求尚未确认，请重试原请求');if(taskState.value===null)taskState.value='READY';emit('changed');beginObservation(ack.taskId);}catch(cause){if(turn===epoch){processing.value=false;error.value=cause instanceof Error?cause.message:'处理尚未完成，请重试。';}}}
const stop=watch(()=>[actor(),props.meetingId,props.active,props.observedTaskId,props.observedInputId,queue.items.value.map(i=>i.fileId??'').filter(Boolean).join(',')],()=>void load(),{immediate:true});const stopTask=watch(()=>[queue.importCommand.ack.value?.taskId,props.active],()=>{const task=queue.importCommand.ack.value?.taskId;if(task&&props.active&&queue.importCommand.state.value==='ACKNOWLEDGED'){beginObservation(task);}},{immediate:true});const effectiveState=computed(()=>taskState.value??props.observedTask??null),hasTask=computed(()=>!!props.taskPresent||!!effectiveState.value||queue.importCommand.state.value==='ACKNOWLEDGED'),failed=computed(()=>['FAILED','CANCELLED','STALE'].includes(effectiveState.value??'')),ready=computed(()=>effectiveState.value==='SUCCEEDED');
watch(dock,node=>{observer?.disconnect();observer=null;if(node&&typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(()=>document.documentElement.style.setProperty('--acf-height',Math.ceil(node.getBoundingClientRect().height)+'px'));observer.observe(node);}},{flush:'post'});
onUnmounted(()=>{stop();stopTask();observer?.disconnect();reset();});
</script>
<template>
 <div v-if="!hasTask&&!recorded&&!loading" class="card card-p"><div class="banner info">尚未开始处理，请先提交会议文件。</div><button class="btn primary" @click="emit('editFiles')">继续导入</button><p v-if="error" class="ac-error mt12" role="alert">{{error}} <button class="btn sm ghost" @click="load">重新读取</button></p></div>
 <div v-else class="card">
  <div class="card-h" :class="hasTask?'aci-processing-top':''"><div><div class="card-t">材料导入与解析</div><div class="small muted mt8">{{hasTask?(failed?'转写处理失败，原文件、已有结果及人工修订保留。':ready?'解析处理已完成。':'正在解析会议内容及补充材料，完成后解锁转写校正。'):'录音已自动关联，无需重复上传；可继续补充背景资料。'}}</div></div><span class="ml-a"></span><button v-if="!hasTask" class="btn sm" @click="emit('materials','materials')">添加背景资料</button></div>
  <div class="card-p"><p v-if="error" class="ac-error" role="alert">{{error}} <button class="btn sm ghost" :disabled="processing" @click="load">重新读取</button></p><div :class="hasTask?'aci-material-grid':''">
   <section><h3>会议主文件 <span v-if="hasTask" class="small muted">{{files.length}} 个</span></h3><p v-if="loading" class="small muted" role="status">正在读取会议主文件…</p>
    <div v-for="file in files" :key="file.fileId" class="aci-progress-file"><div class="aci-progress-file-top"><span class="aci-file-type"><Icon :name="['MP4','MOV','MKV'].includes(importFormat(file.displayName)??'')?'play':['MP3','WAV','M4A','WEBM'].includes(importFormat(file.displayName)??'')?'mic':'file'" :size="18"/></span><div class="aci-progress-name"><b :title="file.displayName">{{file.displayName}}</b><div class="small muted">会议主文件 · {{importFormat(file.displayName)??'文件'}}</div></div><span class="tag" :class="failed?'red':ready?'green':'orange'">{{hasTask?(failed?'处理失败':ready?'识别及转写完成':'正在识别'):file.intakeEligibility.state==='ELIGIBLE'?'可用':'待核对'}}</span></div><div v-if="hasTask" class="progress mt12"><div class="bar" :style="{width:ready?'100%':'0%'}"></div></div></div><div v-if="!files.length&&!loading" class="aci-empty-material">尚未导入主文件</div>
   </section>
   <section><div v-if="!hasTask" class="divider"></div><div :class="hasTask?'aci-material-section-title':'ac-material-heading'"><h3>{{hasTask?'背景材料及相关文档':'会议背景材料及相关文档'}} <span class="small muted">{{hasTask?'0 个':'（选填）'}}</span></h3><button v-if="hasTask" class="btn sm" @click="emit('materials','materials')">调整背景材料</button><div v-else class="flex wrap"><button class="btn" @click="emit('materials','local')">上传本地文件</button><button class="btn" @click="emit('materials','library')">从知识库选择</button></div></div><div class="aci-empty-material">{{hasTask?'未添加背景材料，将基于会议主文件处理。':'未添加背景材料，将基于录音处理。'}}</div></section>
  </div><p v-if="more" class="small muted mt16">文件超过单批处理数量，请通过导入窗口核对本次文件。</p><div v-if="!hasTask" class="small muted mt16" role="status">录音和材料已就绪，点击开始处理继续。</div><div v-if="!hasTask" class="aci-process-actions"><button class="btn primary" :disabled="!canStart" @click="start">{{queue.importCommand.state.value==='UNCERTAIN'?'重试原处理请求':'开始处理'}}</button></div></div>
 </div>
 <footer v-if="active&&hasTask&&!confirmed" ref="dock" class="acf-dock" role="region" aria-label="当前步骤确认操作"><div class="acf-inner"><div class="acf-hint">{{failed?'处理失败，请查看原因后重试；已有内容保留。':ready?'材料解析处理已完成，核对后进入转写校正。':'材料尚未处理完成，请先完成解析或处理异常。'}}</div><div class="acf-actions"><button v-if="failed" class="btn primary" :disabled="!canStart" @click="start">重试处理</button><button v-else-if="queue.importCommand.state.value==='UNCERTAIN'" class="btn primary" :disabled="processing" @click="start">重试原处理请求</button><button v-else class="btn primary" :disabled="!ready" @click="emit('processed')">进入转写校正</button></div></div></footer>
</template>
